// src/actix/api/cluster_api.rs:60-73
#[post("/cluster/recover")]
fn recover_current_peer(
    dispatcher: web::Data<Dispatcher>,
    ActixAuth(auth): ActixAuth,
) -> impl Future<Output = HttpResponse> {
    let pass = new_unchecked_verification_pass();
    helpers::time(async move {
        auth.check_global_access(AccessRequirements::new().manage(), "recover_current_peer")?;
        dispatcher.toc(&auth, &pass).request_snapshot()?;
        Ok(true)
    })
}

// lib/storage/src/content_manager/toc/mod.rs:545-550
pub fn request_snapshot(&self) -> Result<(), StorageError> {
    self.get_consensus_proposal_sender()?
        .send(ConsensusOperations::request_snapshot())?;
    Ok(())
}

// lib/storage/src/content_manager/toc/mod.rs:775-778
fn get_consensus_proposal_sender(&self) -> Result<&Sender<ConsensusOperations>, StorageError> {
    self.consensus_proposal_sender
        .as_ref()
        .ok_or_else(|| StorageError::service_error("Qdrant is running in standalone mode"))
}
